def config_modules(topic, config):
    modules = []
    keys = ['foundation', 'metrics', 'practice', 'risk']
    labels = config['nav']
    for idx, key in enumerate(keys):
        sections = [section('核心定義與範圍', config[key][0])]
        sections.extend(section(f'深入拆解：{labels[idx]}', html) for html in config[key][1:])
        modules.append(module(f"{topic['slug']}-{key}", labels[idx], f'CHAPTER {idx + 1:02d} / {key.upper()}', config['titles'][idx], config['diagrams'][idx], sections, topic.get('tool')))
    topic['chapter_nav'] = [(item['id'], item['nav']) for item in modules]
    return modules
